Proof. vm_compute. reflexivity. Qed.

Lemma zz2_small_trim_b : zzId (plq_eqb (ptrim [1;2;0]) [(1#1)%Q; (2#1)%Q]) true.
Proof. vm_compute. reflexivity. Qed.

