Lemma zz2_small_div_d1 : zzId (andb (plq_eqb (fst (pdivmod [(1#1)%Q; (2#1)%Q; (1#1)%Q] [(1#1)%Q; (1#1)%Q])) [(1#1)%Q; (1#1)%Q])
                                   (plq_eqb (snd (pdivmod [(1#1)%Q; (2#1)%Q; (1#1)%Q] [(1#1)%Q; (1#1)%Q])) [(0#1)%Q])) true.
Proof. vm_compute. reflexivity. Qed.

